        data: {"result": {"minY": 1326.0, "minX": 0.0, "maxY": 1366.0, "series": [{"data": [[0.0, 1357.0]], "isOverall": false, "label": "2. GET /api/products (Read-heavy)", "isController": false}, {"data": [[0.0, 1351.0]], "isOverall": false, "label": "3. GET /api/products/:id (Read-heavy)", "isController": false}, {"data": [[0.0, 1326.0]], "isOverall": false, "label": "5. POST /api/checkout (Transactional)", "isController": false}, {"data": [[0.0, 1366.0]], "isOverall": false, "label": "1. POST /api/login (Auth-heavy)", "isController": false}, {"data": [[0.0, 1339.0]], "isOverall": false, "label": "4. POST /api/cart (Transactional)", "isController": false}], "supportsControllersDiscrimination": true, "granularity": 100, "maxX": 4.9E-324, "title": "Response Time Distribution"}},
